FUNCTION_BLOCK FB_Task
VAR_INPUT
  DO_LOW : BOOL;
  AERATION_E_STOP_NC : BOOL;
END_VAR
VAR_OUTPUT
  BLOWER_RUN : BOOL;
  AERATION_BLOWER_CYCLE_COUNT : UINT;
END_VAR
VAR
  tonStartDelay : TON;
  rtPermit : R_TRIG? 
  bRunPrev : BOOL;
